<?php require 'config/bootstrap.php'; require_login(); require 'includes/upload.php'; $id=(int)($_GET['id']??0); $c=own_contract($id); $pdo=db();
function paras(string $t): array { return array_values(array_filter(array_map('trim',preg_split('/\R+/',$t)),fn($x)=>$x!=='')); }
function diff_paras(array $a,array $b): ?array { $n=count($a);$m=count($b); if($n*$m>1000000) return null; $L=array_fill(0,$n+1,array_fill(0,$m+1,0));
 for($i=$n-1;$i>=0;$i--) for($j=$m-1;$j>=0;$j--) $L[$i][$j]=$a[$i]===$b[$j]?$L[$i+1][$j+1]+1:max($L[$i+1][$j],$L[$i][$j+1]);
 $o=[];$i=$j=0; while($i<$n&&$j<$m){ if($a[$i]===$b[$j]){$o[]=['same',$a[$i]];$i++;$j++;} elseif($L[$i+1][$j]>=$L[$i][$j+1]){$o[]=['del',$a[$i++]];} else {$o[]=['add',$b[$j++]];} }
 while($i<$n)$o[]=['del',$a[$i++]]; while($j<$m)$o[]=['add',$b[$j++]]; return $o; }
if($_SERVER['REQUEST_METHOD']==='POST'){ csrf_check();
 if(($_POST['do']??'')==='upload'){ $lbl=trim($_POST['label']??'')?:'new version'; $er=store_upload($pdo,$id,$_FILES['doc']??[],$lbl); if($er)flash($er,'error'); else { log_act('version_uploaded',$id,$lbl); flash('Version stored. Earlier versions are preserved.'); } }
 header("Location: compare.php?id=$id"); exit; }
$v=$pdo->prepare('SELECT * FROM contract_versions WHERE contract_id=? ORDER BY id');$v->execute([$id]);$vers=$v->fetchAll(); $byid=array_column($vers,null,'id');
$old=(int)($_GET['old']??0);$new=(int)($_GET['new']??0);$diff=null;$err='';
if($old&&$new){ if(!isset($byid[$old],$byid[$new])||$old===$new) $err='Choose two different versions of this contract.'; elseif(trim($byid[$old]['extracted_text'])===''||trim($byid[$new]['extracted_text'])==='') $err='One of the versions has no extracted text, so it cannot be compared. Paste its text on the contract page first.';
 else { $diff=diff_paras(paras($byid[$old]['extracted_text']),paras($byid[$new]['extracted_text'])); if($diff===null) $err='Documents are too large for the built-in comparison.'; else { $ad=count(array_filter($diff,fn($d)=>$d[0]==='add'));$rm=count(array_filter($diff,fn($d)=>$d[0]==='del')); $pdo->prepare('INSERT INTO contract_comparisons(contract_id,old_version_id,new_version_id,added_count,removed_count) VALUES(?,?,?,?,?)')->execute([$id,$old,$new,$ad,$rm]); log_act('versions_compared',$id,"$old vs $new"); } } }
$h=$pdo->prepare('SELECT * FROM contract_comparisons WHERE contract_id=? ORDER BY id DESC LIMIT 10');$h->execute([$id]);$hist=$h->fetchAll();
page_head('Versions'); ?><a href="contract.php?id=<?=$id?>">&larr; <?=e($c['title'])?></a><h1 class="h3 my-3">Versions and comparison</h1>
<div class="alert alert-secondary">Basic paragraph-level text diff only. Semantic matching, change-significance scoring and risk deltas are not implemented.</div>
<div class="cardx mb-3"><h2 class="h6">Add a version</h2><form method="post" enctype="multipart/form-data" class="row g-2"><?=csrf_field()?><input type="hidden" name="do" value="upload"><div class="col-md-3"><input class="form-control" name="label" placeholder="Label, e.g. v2"></div><div class="col-md-6"><input class="form-control" type="file" name="doc" accept=".pdf,.docx,.txt" required></div><div class="col-auto"><button class="btn btn-primary">Upload</button></div></form></div>
<div class="cardx mb-3"><h2 class="h6">Compare</h2><?php if(count($vers)<2):?><div class="empty">At least two versions are needed.</div><?php else:?><form class="row g-2"><input type="hidden" name="id" value="<?=$id?>"><?php foreach(['old'=>'Older','new'=>'Newer'] as $k=>$lb):?><div class="col-md-4"><select class="form-select" name="<?=$k?>"><?php foreach($vers as $x):?><option value="<?=$x['id']?>" <?=($k==='old'?$old:$new)==$x['id']?'selected':''?>><?=$lb?>: <?=e($x['version_label'])?> (<?=e($x['uploaded_at'])?>, <?=e($x['extraction_status'])?>)</option><?php endforeach;?></select></div><?php endforeach;?><div class="col-auto"><button class="btn btn-primary">Compare</button></div></form><?php endif; if($err):?><div class="alert alert-danger mt-3"><?=e($err)?></div><?php endif;?></div>
<?php if($diff):?><div class="cardx mb-3"><h2 class="h6">Differences</h2><?php $shown=0; foreach($diff as [$t,$s]){ if($t==='same') continue; $shown++; ?><div class="p-2 mb-1 rounded" style="background:<?=$t==='add'?'rgba(56,201,150,.15)':'rgba(255,113,133,.15)'?>"><strong><?=$t==='add'?'Added':'Removed'?>:</strong> <?=e($s)?></div><?php } if(!$shown):?><div class="empty">The extracted texts are identical.</div><?php endif;?></div><?php endif;?>
<div class="cardx"><h2 class="h6">Comparison history</h2><?php if(!$hist):?><div class="empty">No comparisons yet.</div><?php endif; foreach($hist as $x):?><p class="mb-1"><?=e($byid[$x['old_version_id']]['version_label']??'?')?> &rarr; <?=e($byid[$x['new_version_id']]['version_label']??'?')?>: +<?=$x['added_count']?> / -<?=$x['removed_count']?> paragraphs <span class="text-muted">· <?=e($x['created_at'])?></span></p><?php endforeach;?></div><?php page_foot();
